            for x in col:
                if x==v: cur+=1
                else:
                    if cur>runs: runs=max(runs,cur); cur=0
            if cur>runs: runs=max(runs,cur)
            if runs>=best[0]: best=(runs,v,cc)
    n,v,c=best
    nz=[rr for rr in range(H) if any(g[rr][x]!=0 for x in range(c+1,W))]
    top=nz[0]; last=nz[-1]
    hh=last-top+1
    blk=[[g[rr][x] for x in range(c+1,W)] for rr in range(top,last+1)]
    out=[]
    for rr in range(H):
        row=g[rr][:]
        if g[rr][c]==v:
            kk=(rr-top)%hh
            row[:]=[v]+blk[kk]
